/**
 * Result returned after analyzing an audio frame chunk (16kHz PCM 16-bit mono).
 */
data class AudioAnalysisResult (
    /**
     * Normalized root-mean-square amplitude in range [0.0, 1.0].
     * Used by the Compose waveform visualizer to animate sound waves.
     */
    var `rmsLevel`: kotlin.Float, 
    /**
     * Whether this chunk contains active speech energy above the noise floor.
     */
    var `isSpeech`: kotlin.Boolean, 
    /**
     * True when speech was previously detected and silence has continuously
     * exceeded the 1.5-second threshold (VAD auto-stop trigger).
     */
    var `silenceTimeoutTriggered`: kotlin.Boolean, 
    /**
     * Total duration of speech processed so far in milliseconds.
     */
    var `totalSpeechMs`: kotlin.UInt
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAudioAnalysisResult: FfiConverterRustBuffer<AudioAnalysisResult> {
    override fun read(buf: ByteBuffer): AudioAnalysisResult {
        return AudioAnalysisResult(
            FfiConverterFloat.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterUInt.read(buf),
        )
    }

    override fun allocationSize(value: AudioAnalysisResult) = (
            FfiConverterFloat.allocationSize(value.`rmsLevel`) +
            FfiConverterBoolean.allocationSize(value.`isSpeech`) +
            FfiConverterBoolean.allocationSize(value.`silenceTimeoutTriggered`) +
            FfiConverterUInt.allocationSize(value.`totalSpeechMs`)
    )

    override fun write(value: AudioAnalysisResult, buf: ByteBuffer) {
            FfiConverterFloat.write(value.`rmsLevel`, buf)
            FfiConverterBoolean.write(value.`isSpeech`, buf)
            FfiConverterBoolean.write(value.`silenceTimeoutTriggered`, buf)
            FfiConverterUInt.write(value.`totalSpeechMs`, buf)
    }
}



