sealed class LekhaniException: kotlin.Exception() {
    
    class SessionException(
        
        val v1: kotlin.String
        ) : LekhaniException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidLayout(
        
        val v1: kotlin.String
        ) : LekhaniException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidInput(
        
        val v1: kotlin.String
        ) : LekhaniException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class IndexOutOfBounds(
        
        val v1: kotlin.UInt
        ) : LekhaniException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LekhaniException> {
        override fun lift(error_buf: RustBuffer.ByValue): LekhaniException = FfiConverterTypeLekhaniError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLekhaniError : FfiConverterRustBuffer<LekhaniException> {
    override fun read(buf: ByteBuffer): LekhaniException {
        

        return when(buf.getInt()) {
            1 -> LekhaniException.SessionException(
                FfiConverterString.read(buf),
                )
            2 -> LekhaniException.InvalidLayout(
                FfiConverterString.read(buf),
                )
            3 -> LekhaniException.InvalidInput(
                FfiConverterString.read(buf),
                )
            4 -> LekhaniException.IndexOutOfBounds(
                FfiConverterUInt.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LekhaniException): ULong {
        return when(value) {
            is LekhaniException.SessionException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LekhaniException.InvalidLayout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LekhaniException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LekhaniException.IndexOutOfBounds -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: LekhaniException, buf: ByteBuffer) {
        when(value) {
            is LekhaniException.SessionException -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LekhaniException.InvalidLayout -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LekhaniException.InvalidInput -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LekhaniException.IndexOutOfBounds -> {
                buf.putInt(4)
                FfiConverterUInt.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




enum class LekhaniLayoutType {
    
    /**
     * Ergonomic two-thumb flow layout (Vowels on left, Consonants on right)
     */
    PROBAHO,
    /**
     * Classic phonetic transliteration
     */
    AVRO,
    /**
     * Official Bangladesh BBS fixed standard (National / জাতীয়)
     */
    NATIONAL,
    /**
     * Popular phonetic fixed layout (Probhat / प्रभात)
     */
    PROBHAT,
    /**
     * Google Gboard style Bengali fixed mapping
     */
    GBOARD,
    /**
     * Standard English QWERTY
     */
    ENGLISH;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeLekhaniLayoutType: FfiConverterRustBuffer<LekhaniLayoutType> {
    override fun read(buf: ByteBuffer) = try {
        LekhaniLayoutType.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: LekhaniLayoutType) = 4UL

    override fun write(value: LekhaniLayoutType, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceShort: FfiConverterRustBuffer<List<kotlin.Short>> {
    override fun read(buf: ByteBuffer): List<kotlin.Short> {
        val len = buf.getInt()
        return List<kotlin.Short>(len) {
            FfiConverterShort.read(buf)
        }
    }

    override fun allocationSize(value: List<kotlin.Short>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterShort.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<kotlin.Short>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterShort.write(it, buf)
        }
    }
}




